import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ListZipperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<String> names(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    static List<Integer> scores(Integer... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    public static void main(String[] args) {
        try {
            check("zip of three pairs",
                    "[PairEntry[name=ana, score=90], PairEntry[name=bo, score=80], PairEntry[name=cy, score=70]]",
                    ListZipper.zip(names("ana", "bo", "cy"), scores(90, 80, 70)).toString());
            check("zip stops at the shorter list", 1,
                    ListZipper.zip(names("ana"), scores(1, 2, 3)).size());
            check("zip with more names than scores",
                    "[PairEntry[name=ana, score=5]]",
                    ListZipper.zip(names("ana", "bo"), scores(5)).toString());
            check("zip of two empty lists", "[]",
                    ListZipper.zip(names(), scores()).toString());
            check("zip when scores are empty", 0,
                    ListZipper.zip(names("ana", "bo"), scores()).size());
            check("labels of a zipped list", "[ana=90, bo=80, cy=70]",
                    ListZipper.labels(ListZipper.zip(names("ana", "bo", "cy"), scores(90, 80, 70))).toString());
            check("labels keeps negative scores", "[cold=-4]",
                    ListZipper.labels(ListZipper.zip(names("cold"), scores(-4))).toString());
            check("labels of an empty list", "[]",
                    ListZipper.labels(new ArrayList<PairEntry>()).toString());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

