import java.util.ArrayList;
import java.util.List;

record PairEntry(String name, int score) { }

public class ListZipper {

    public static List<PairEntry> zip(List<String> names, List<Integer> scores) {
        List<PairEntry> pairs = new ArrayList<>();
        int shared = Math.min(names.size(), scores.size());
        for (int i = 0; i < shared; i++) {
            pairs.add(new PairEntry(names.get(i), scores.get(i)));
        }
        return pairs;
    }

    public static List<String> labels(List<PairEntry> pairs) {
        List<String> result = new ArrayList<>();
        for (PairEntry pair : pairs) {
            result.add(pair.name() + "=" + pair.score());
        }
        return result;
    }
}
